begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.k(n integer) returns uuid language sql immutable as $$select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.loc(p_repo text default '12') returns jsonb language sql immutable as $$select jsonb_build_object('provider','github','kind','issue','repositoryId',p_repo,'repository','fictional/startup','id','42')$$;
insert into auth.users(id,email,raw_user_meta_data) select pg_temp.k(n),'integrations-'||n||'@example.test','{}' from generate_series(1,5)n;
insert into public.organizations(id,name,created_by) values(pg_temp.k(10),'Integration Alpha',pg_temp.k(1)),(pg_temp.k(11),'Integration Beta',pg_temp.k(4));
insert into public.memberships(organization_id,user_id,role) values(pg_temp.k(10),pg_temp.k(1),'OWNER'),(pg_temp.k(10),pg_temp.k(2),'MEMBER'),(pg_temp.k(10),pg_temp.k(3),'VIEWER'),(pg_temp.k(10),pg_temp.k(5),'MEMBER'),(pg_temp.k(11),pg_temp.k(4),'OWNER');
select set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
insert into public.tasks(id,organization_id,title,created_by,updated_by) values(pg_temp.k(20),pg_temp.k(10),'Fictional implementation',pg_temp.k(1),pg_temp.k(1));
select set_config('request.jwt.claim.sub',pg_temp.k(4)::text,true);
insert into public.tasks(id,organization_id,title,created_by,updated_by) values(pg_temp.k(21),pg_temp.k(11),'Private foreign work',pg_temp.k(4),pg_temp.k(4));
select public.activate_integration(pg_temp.k(1),pg_temp.k(10),pg_temp.k(30),'github','1','Fictional App','{"installationId":"1","repositories":[{"id":"12","fullName":"fictional/startup"}]}','encrypted-fixture',0);
select public.activate_integration(pg_temp.k(2),pg_temp.k(10),pg_temp.k(31),'google-drive','fictional-id','owner@example.test','{}','encrypted-fixture',0);
select public.activate_integration(pg_temp.k(2),pg_temp.k(10),pg_temp.k(32),'google-calendar','fictional-id','owner@example.test','{}','encrypted-fixture',0);
select public.activate_integration(pg_temp.k(4),pg_temp.k(11),pg_temp.k(33),'github','2','Foreign App','{"installationId":"2","repositories":[{"id":"13","fullName":"foreign/private"}]}','encrypted-fixture',0);
select throws_ok($$select public.activate_integration(pg_temp.k(2),pg_temp.k(10),pg_temp.k(34),'github','1','No','{}','x',0)$$,'42501',null,'service activation still checks GitHub manager role');
select throws_ok($$select public.activate_integration(pg_temp.k(4),pg_temp.k(10),pg_temp.k(34),'google-drive','1','No','{}','x',0)$$,'42501',null,'service activation checks active organization membership');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
select is((select count(*)::int from public.integration_connections),1,'owner sees organization GitHub, not another user Google or foreign connection');
select throws_ok($$select * from public.integration_secrets$$,'42501',null,'credentials cannot be selected');
select throws_ok($$select * from public.integration_oauth_states$$,'42501',null,'OAuth state cannot be selected');
select throws_ok($$select * from public.integration_resource_cache$$,'42501',null,'cached metadata cannot be selected directly');
select throws_ok($$select * from public.integration_calendar_intents$$,'42501',null,'Calendar receipts cannot be selected directly');
select throws_ok($$update public.integration_connections set status='connected'$$,'42501',null,'direct connection writes denied');
select throws_ok($$select public.store_integration_secret(pg_temp.k(30),1,'secret')$$,'42501',null,'credential RPC service-only');
select throws_ok($$select public.activate_integration(pg_temp.k(1),pg_temp.k(10),pg_temp.k(30),'github','1','X','{}','x',1)$$,'42501',null,'activation RPC cannot be called by browser');
select throws_ok($$select public.store_integration_cache(pg_temp.k(30),1,'[]')$$,'42501',null,'cache RPC service-only');
select lives_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(20),pg_temp.k(30),pg_temp.loc(),false)$$,'owner explicitly links selected repository issue');
select lives_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(20),pg_temp.k(30),pg_temp.loc(),false)$$,'repeated attachment idempotent');
select is((select count(*)::int from public.external_resource_links),1,'one link after duplicate submit');
select throws_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(20),pg_temp.k(33),pg_temp.loc(),false)$$,'42501',null,'foreign connection denied');
select throws_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(21),pg_temp.k(30),pg_temp.loc(),false)$$,'42501',null,'foreign target denied');
select throws_ok($$select public.set_external_resource_link(pg_temp.k(11),'core.task',pg_temp.k(21),pg_temp.k(33),pg_temp.loc(),false)$$,'42501',null,'forged organization denied');
select throws_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(20),pg_temp.k(30),pg_temp.loc('99'),false)$$,'42501',null,'unselected repository denied');
select throws_ok($$select public.set_external_resource_link(pg_temp.k(10),'unknown.work',pg_temp.k(20),pg_temp.k(30),pg_temp.loc(),false)$$,'42501',null,'unregistered target denied');
select throws_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(20),pg_temp.k(31),'{"provider":"google-drive","kind":"file","id":"file_a"}',false)$$,'42501',null,'other user Drive attachment denied even for owner');
select set_config('request.jwt.claim.sub',pg_temp.k(2)::text,true);
select is((select count(*)::int from public.integration_connections),3,'user sees own Google capabilities and organization GitHub');
select lives_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(20),pg_temp.k(31),'{"provider":"google-drive","kind":"file","id":"file_a"}',false)$$,'Google owner explicitly shares one reference');
select throws_ok($$select public.disconnect_integration(pg_temp.k(10),pg_temp.k(30))$$,'42501',null,'member cannot disconnect organization GitHub');
select set_config('request.jwt.claim.sub',pg_temp.k(3)::text,true);
select is((select count(*)::int from public.external_resource_links),2,'viewer reads only shared references through authorized target');
select throws_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(20),pg_temp.k(30),pg_temp.loc(),false)$$,'42501',null,'viewer attachment denied');
select throws_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(20),pg_temp.k(30),pg_temp.loc(),true)$$,'42501',null,'viewer unlink denied');
select throws_ok($$select public.disconnect_integration(pg_temp.k(10),pg_temp.k(31))$$,'42501',null,'viewer cannot disconnect another user Google');
select set_config('request.jwt.claim.sub',pg_temp.k(4)::text,true);
select is((select count(*)::int from public.external_resource_links),0,'foreign organization cannot see any links');
select is((select count(*)::int from public.integration_connections),1,'foreign organization sees only its own connection');
select set_config('request.jwt.claim.sub',pg_temp.k(5)::text,true);
select lives_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(20),pg_temp.k(31),'{"provider":"google-drive","kind":"file","id":"file_a"}',true)$$,'authorized editor can unlink shared reference without provider deletion');
select is((select count(*)::int from public.external_resource_links),1,'unlink changes reference only');
select set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
select public.save_core_note(pg_temp.k(10),pg_temp.k(40),'Fictional note','Working context',false,null);
select public.save_milestone(pg_temp.k(10),pg_temp.k(41),'Fictional milestone','',current_date+7,'ACTIVE',null,false,null);
select lives_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.note',pg_temp.k(40),pg_temp.k(30),pg_temp.loc(),false)$$,'Note target uses shared contract');
select lives_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.milestone',pg_temp.k(41),pg_temp.k(30),pg_temp.loc(),false)$$,'Milestone target uses shared contract');
reset role;
update public.notes set archived_at=clock_timestamp() where id=pg_temp.k(40);
set local role authenticated;
select throws_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.note',pg_temp.k(40),pg_temp.k(30),pg_temp.loc(),false)$$,'42501',null,'archived target cannot acquire new links');
reset role;
select public.store_integration_cache(pg_temp.k(30),1,'[{"key":"fixture","projection":{"title":"Fictional metadata"}}]');
-- Service-side lifecycle checks concern this fixture connection. Other tenants'
-- cached metadata must neither affect the count nor be removed by disconnect.
select is((select count(*)::int from public.integration_resource_cache where connection_id=pg_temp.k(30)),1,'server cache persists bounded metadata');
set local role authenticated;
select lives_ok($$select public.disconnect_integration(pg_temp.k(10),pg_temp.k(30))$$,'manager disconnect succeeds');
select is((select count(*)::int from public.external_resource_links),3,'disconnect retains all Stylus references');
select throws_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(20),pg_temp.k(30),pg_temp.loc(),false)$$,'42501',null,'disconnected connection cannot attach');
reset role;
select is((select count(*)::int from public.integration_resource_cache where connection_id=pg_temp.k(30)),0,'disconnect clears metadata cache');
select is((select count(*)::int from public.integration_secrets where connection_id=pg_temp.k(30)),0,'disconnect clears credentials');
select is(public.store_integration_secret(pg_temp.k(30),1,'stale-secret'),false,'late refresh cannot resurrect disconnected credentials');
select public.store_integration_cache(pg_temp.k(30),1,'[{"key":"late","projection":{"title":"Must not return"}}]');
select is((select count(*)::int from public.integration_resource_cache where connection_id=pg_temp.k(30)),0,'late provider response cannot resurrect cache');
select throws_ok($$select public.activate_integration(pg_temp.k(1),pg_temp.k(10),pg_temp.k(30),'github','1','X','{}','sealed',1)$$,'PT409',null,'late OAuth callback cannot override disconnect generation');
update public.memberships set removed_at=clock_timestamp() where user_id=pg_temp.k(2) and organization_id=pg_temp.k(10);
select is(public.store_integration_secret(pg_temp.k(31),1,'late-secret'),false,'removed user credential refresh denied');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.k(2)::text,true);
select is((select count(*)::int from public.integration_connections),0,'removed member cannot see old connections');
select is((select count(*)::int from public.external_resource_links),0,'removed member cannot see old links');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
select public.activate_integration(pg_temp.k(1),pg_temp.k(10),pg_temp.k(30),'github','1','Fictional App','{"installationId":"1","repositories":[{"id":"12","fullName":"fictional/startup"}]}','encrypted-fixture',2);
select public.set_organization_plugin_enabled(pg_temp.k(10),'marketing',true);
insert into public.marketing_hypotheses(id,organization_id,title,statement,created_by,updated_by) values(pg_temp.k(50),pg_temp.k(10),'Fictional hypothesis','A fictional testable belief',pg_temp.k(1),pg_temp.k(1));
insert into public.marketing_experiments(id,organization_id,hypothesis_id,title,created_by,updated_by) values(pg_temp.k(51),pg_temp.k(10),pg_temp.k(50),'Fictional experiment',pg_temp.k(1),pg_temp.k(1));
insert into public.tasks(id,organization_id,title,created_by,updated_by) values(pg_temp.k(22),pg_temp.k(10),'Bounded resources fixture',pg_temp.k(1),pg_temp.k(1));
set local role authenticated;
select lives_ok($$select public.set_external_resource_link(pg_temp.k(10),'marketing.hypothesis',pg_temp.k(50),pg_temp.k(30),pg_temp.loc(),false)$$,'Hypothesis adapter registered through trusted migration');
select lives_ok($$select public.set_external_resource_link(pg_temp.k(10),'marketing.experiment',pg_temp.k(51),pg_temp.k(30),pg_temp.loc(),false)$$,'Experiment adapter uses the same resource model');
select public.set_organization_plugin_enabled(pg_temp.k(10),'marketing',false);
select is((select count(*)::int from public.external_resource_links where entity_type like 'marketing.%'),0,'disabled plugin hides its reference rows');
select throws_ok($$select public.set_external_resource_link(pg_temp.k(10),'marketing.experiment',pg_temp.k(51),pg_temp.k(30),pg_temp.loc(),false)$$,'42501',null,'disabled plugin cannot attach');
do $$begin for n in 1..20 loop perform public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(22),pg_temp.k(30),jsonb_set(pg_temp.loc(),'{id}',to_jsonb(n::text)),false);end loop;end$$;
select is((select count(*)::int from public.external_resource_links where entity_id=pg_temp.k(22)),20,'one entity supports twenty bounded references');
select throws_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(22),pg_temp.k(30),jsonb_set(pg_temp.loc(),'{id}','"21"'),false)$$,'22023',null,'twenty-first reference denied atomically');
set local role anon;
select throws_ok($$select * from public.integration_connections$$,'42501',null,'anonymous connection reads denied');
select throws_ok($$select public.set_external_resource_link(pg_temp.k(10),'core.task',pg_temp.k(20),pg_temp.k(30),pg_temp.loc(),false)$$,'42501',null,'anonymous resource writes denied');
reset role;
select * from finish();
rollback;
